# conceptual example (async)
async for ev in StreamingFragmenter.from_stream(response_stream, policy=RetryPolicy(max_fragment_retries=2)).stream_as_context():
    if ev.type == 'token':
        render_token(ev.text)
    elif ev.type == 'checkpoint':
        commit_ui_checkpoint(ev.fragment_id)
    elif ev.type == 'error':
        show_error_banner(ev.message)

